{
  "findings": [
    {
      "check_id": "CKV_AWS_15",
      "title": "Ensure all data stored in the AMI is securely encrypted at rest",
      "resource": "aws_ami.pass",
      "severity": "HIGH",
      "explanation": "The first ebs_block_device (root volume) does not have 'encrypted = true' set. While the second block device is encrypted, the root device containing the OS and potentially sensitive data is left unencrypted by default."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
    encrypted   = true
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }
}
",
  "fix_summary": "Added 'encrypted = true' to the first ebs_block_device definition to ensure the root volume is encrypted at rest, matching the security posture of the second block device."
}
